'use strict';
// The 84-day challenge is private learner activity, never a ranking or currency.
let chView='progress',chWeek=0,chDay=0,chError='',chLoadError='',chLoading=false,chLoadEpoch=0,chClock=null,chRenderedDate='',chCalendarMonth='',chCalendarOpener=null;
let chSelection={bank:'nw',topic:''};
const chFormatters=new Map();
function chNow(){return Date.now()}
function chId(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('')}
// Older browsers and HTTP previews may lack this API used by the existing journal.
if(typeof crypto.randomUUID!=='function')crypto.randomUUID=()=>{const h=chId();return `${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-${((parseInt(h[16],16)&3)|8).toString(16)}${h.slice(17,20)}-${h.slice(20)}`};
function chOwner(){return cloudEnabled?(cloudUser?.id||'signed-out'):'local'}
function chReady(){return !!state.hubOnboardingCompleted&&(!cloudEnabled||cloudReady&&!cloudRecovery&&!cloudReviewRecovery&&!!cloudUser)}
function chRecord(){return learningData().challenge84||null}
function chZone(){try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}catch{return 'UTC'}}
function chValidZone(zone){try{new Intl.DateTimeFormat('en',{timeZone:zone}).format();return true}catch{return false}}
function chDate(now=chNow(),zone=chRecord()?.timeZone||chZone()){if(!chFormatters.has(zone))chFormatters.set(zone,new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}));const p=Object.fromEntries(chFormatters.get(zone).formatToParts(new Date(now)).map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`}}
function chDayNumber(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return NaN;const n=Date.parse(date+'T00:00:00Z');return Number.isFinite(n)&&new Date(n).toISOString().slice(0,10)===date?n/86400000:NaN}
function chAdd(date,days){return new Date((chDayNumber(date)+days)*86400000).toISOString().slice(0,10)}
function chFriendly(date){return new Date(date+'T12:00:00Z').toLocaleDateString('en',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'})}
function chIndex(c=chRecord(),now=chNow()){return c?chDayNumber(chDate(now,c.timeZone).date)-chDayNumber(c.start):-1}
function chOpenDay(day,c=chRecord(),now=chNow()){const current=chIndex(c,now);return !!c&&!c.withdrawnAt&&Number.isInteger(day)&&day>=0&&day<84&&current>=day&&current<84&&Math.floor(day/7)===Math.floor(current/7)}
function chTask(day,c=chRecord()){return c?.days?.[String(day)]||{}}
function chTasksDone(day,c=chRecord()){const row=chTask(day,c);return Number(!!row.journal?.completedAt)+Number(!!row.practice?.done&&!!row.practice.completedAt)}
function chWeekInfo(week,c=chRecord(),now=chNow()){const current=chIndex(c,now),tasks=Array.from({length:7},(_,i)=>chTasksDone(week*7+i,c)).reduce((a,b)=>a+b,0),closed=current>week*7+6;return {week,tasks,start:chAdd(c.start,week*7),end:chAdd(c.start,week*7+6),close:chAdd(c.start,(week+1)*7),closed,status:tasks===14?'Complete':closed?'Incomplete':current<week*7?'Upcoming':c.withdrawnAt?'Not active':'In progress'}}
function chTotals(c=chRecord()){const days=Array.from({length:84},(_,i)=>chTasksDone(i,c)),rounds=Object.values(c?.days||{}).map(d=>d.practice).filter(p=>p?.done&&p.completedAt);return {tasks:days.reduce((a,b)=>a+b,0),days:days.filter(n=>n===2).length,weeks:c?Array.from({length:12},(_,i)=>chWeekInfo(i,c).tasks).filter(n=>n===14).length:0,correct:rounds.reduce((n,p)=>n+(p.score||0),0),answered:rounds.reduce((n,p)=>n+(p.ids?.length||0),0)}}
function chBadges(c=chRecord()){const t=chTotals(c);return [{name:'First step',goal:'Complete one day',earned:t.days>=1},{name:'One full week',goal:'Finish all 14 tasks in a week',earned:t.weeks>=1},{name:'Learning habit',goal:'Complete 28 days',earned:t.days>=28},{name:'Steady learner',goal:'Complete 56 days',earned:t.days>=56},{name:'84 days of progress',goal:'Complete all 168 tasks',earned:t.tasks===168}]}
function chMessage(text){chError=text;const el=document.getElementById('chStatus');if(el)el.textContent=text}
function chJoin(start,timeZone,bank){if(chRecord()){chMessage('Your existing challenge record is kept.');return false}const today=chDate(chNow(),chValidZone(timeZone)?timeZone:'UTC').date;if(!chReady()||!chValidZone(timeZone)||!Number.isFinite(chDayNumber(start))||start<today||start>chAdd(today,30)||!['nw','ew'].includes(bank)){chMessage('Choose a valid start date within 30 days and a valid timezone.');return false}const ok=learningSave(d=>{d.challenge84={version:1,id:chId(),start,timeZone,bank,joinedAt:new Date(chNow()).toISOString(),days:{}}});if(!ok){chMessage(learningMessage);return false}chWeek=0;chDay=0;chView='overview';chError='';render();chSchedule();return true}
function chSetActive(active){const c=chRecord();if(!c||!chReady()||(!c.withdrawnAt)===active)return false;const ok=learningSave(d=>{if(active)delete d.challenge84.withdrawnAt;else d.challenge84.withdrawnAt=new Date(chNow()).toISOString()});if(!ok)chMessage(learningMessage);else{chCloseCalendar();chError='';render();chSchedule()}return ok}
function chNavigate(view='overview',day=null){chLoadEpoch++;chLoading=false;chLoadError='';chError='';if(day!==null){chDay=Math.max(0,Math.min(83,Number(day)||0));chWeek=Math.floor(chDay/7)}else if(view==='overview'&&chRecord())chWeek=Math.max(0,Math.min(11,Math.floor(chIndex()/7)));chView=view;page='progress';render();window.scrollTo(0,0)}
function chStartReflection(day){if(!chReady()||!chOpenDay(day)||chTask(day).journal){chMessage('This reflection is complete or its week is closed.');return false}const c=chRecord();learningDay='';learningOpenEditor();if(!learningDraft||learningNotes().some(n=>n.id===learningDraft.id)){chMessage('Create a new journal reflection for this task.');return false}const linked=learningDraft.challengeTask;if(linked&&(linked.id!==c.id||linked.day!==day)){learningMessage='You have an unfinished challenge draft. Save it first, then open the next reflection.';journalShowStatus();return false}learningDraft.challengeTask={id:c.id,day};learningKeepDraft();learningMessage=`Challenge Day ${day+1} reflection · saved on today’s actual date`;journalShowStatus();return true}
function chCreditReflections(data,before){const c=data.challenge84;if(!c||c.withdrawnAt)return;for(const note of data.notes||[]){const link=note.challengeTask||{id:c.id,day:chIndex(c)};if(link?.id!==c.id||!chOpenDay(link.day,c)||!String(note.body||'').trim()||!String(note.title||'').trim()||before.has(note.id))continue;const used=Object.values(c.days||{}).some(d=>d.journal?.noteId===note.id);if(used)continue;c.days||={};const row=c.days[String(link.day)]||={};if(!row.journal)row.journal={noteId:note.id,completedAt:new Date(chNow()).toISOString()}}}
const chOriginalLearningSave=learningSave;
learningSave=function(change){const before=new Set(learningNotes().map(n=>n.id));return chOriginalLearningSave(data=>{change(data);chCreditReflections(data,before)})};
function chBanks(){return [{id:'nw',title:'OIC NW · Deck'},{id:'ew',title:'OIC EW · Engine'},{id:'olp',title:'OLP modules'},{id:'toolbox-cbt',title:'Toolbox original CBT'}]}
function chBank(id=chSelection.bank){return lhCache.get(id)||reviewBanks.find(b=>b.id===id)}
function chPool(bank=chBank(),topic=chSelection.topic){return (bank?.questions||[]).filter(q=>(!topic||(bank.topics?q.topicId===topic:String(q.set)===String(topic)))&&q.options?.length>=2&&lhCorrect(q).length===1&&!q.needsFigure&&!q.keyWarning&&!/(?:shown|illustrat|diagram|sketch|see figure)/i.test(q.question)&&!state.review.flagged.includes(q.id))}
async function chSelectBank(id){if(!chBanks().some(b=>b.id===id))return;const epoch=++chLoadEpoch,owner=chOwner();chSelection={bank:id,topic:''};chLoading=true;chLoadError='';render();try{await lhLoadBank(id);if(epoch!==chLoadEpoch||owner!==chOwner()||page!=='progress')return;chLoading=false;render()}catch(e){if(epoch!==chLoadEpoch||owner!==chOwner()||page!=='progress')return;chLoading=false;chLoadError=e.message;render()}}
async function chStartPractice(day){if(!chReady()||!chOpenDay(day)||chTask(day).practice?.done){chMessage('This practice is complete or its week is closed.');return false}const c=chRecord(),id=c.id,owner=chOwner(),epoch=++chLoadEpoch,existing=chTask(day).practice,selection={...chSelection};chLoading=true;chLoadError='';render();try{const bank=await lhLoadBank(existing?.bank||selection.bank);if(epoch!==chLoadEpoch||owner!==chOwner()||chRecord()?.id!==id||!chOpenDay(day)||page!=='progress')return false;chLoading=false;if(!existing){const pool=chPool(bank,selection.topic);if(!pool.length){chMessage('No eligible single-answer questions here. Choose another topic or source.');render();return false}const selected=lhShuffle(pool).slice(0,5);const ok=learningSave(d=>{const row=d.challenge84.days[String(day)]||={};row.practice={id:chId(),bank:bank.id,topic:selection.topic,ids:selected.map(q=>q.id),answers:{},index:0,startedAt:new Date(chNow()).toISOString(),done:false}});if(!ok){chMessage(learningMessage);render();return false}}chDay=day;chWeek=Math.floor(day/7);chView='round';chError='';render();return true}catch(e){if(epoch===chLoadEpoch&&owner===chOwner()){chLoading=false;chLoadError=e.message;render()}return false}}
function chRound(){const round=chTask(chDay).practice;return {round,bank:round?chBank(round.bank):null}}
function chChoose(choice){const {round,bank}=chRound(),q=bank?.questions.find(q=>q.id===round?.ids[round.index]);if(!chReady()||!chOpenDay(chDay)||!round||round.done||!q||Object.hasOwn(round.answers,q.id)||!Number.isInteger(choice)||choice<0||choice>=q.options.length)return false;const ok=learningSave(d=>{d.challenge84.days[String(chDay)].practice.answers[q.id]=choice});if(!ok)chMessage(learningMessage);else render();return ok}
function chMoveRound(delta){const {round}=chRound();if(!round||round.done)return;round.index=Math.max(0,Math.min(round.ids.length-1,round.index+delta));render()}
function chFinishPractice(){const {round,bank}=chRound();if(!chReady()||!chOpenDay(chDay)||!round||round.done||!bank||!round.ids.every(id=>Object.hasOwn(round.answers,id))){chMessage('Answer each question and review its feedback before finishing.');return false}const score=round.ids.reduce((n,id)=>{const q=bank.questions.find(q=>q.id===id);return n+Number(q&&lhCorrect(q)[0]===round.answers[id])},0);const ok=learningSave(d=>{const p=d.challenge84.days[String(chDay)].practice;p.done=true;p.score=score;p.completedAt=new Date(chNow()).toISOString()});if(ok){chView='day';chError='';render()}else chMessage(learningMessage);return ok}
function chCurrentSummary(){const c=chRecord();if(!c)return '';const i=chIndex(c);if(c.withdrawnAt)return 'Your challenge is not active. Your record is kept.';if(i<0)return `Starts ${chFriendly(c.start)}`;if(i>=84)return 'The 84-day challenge period has ended.';const w=chWeekInfo(Math.floor(i/7));return `Day ${i+1} of 84 · ${83-i} days after today · Week ${w.week+1}: ${w.tasks}/14 tasks`}
function chReminderCopy(){const c=chRecord(),i=chIndex(c);if(!c||c.withdrawnAt||i<0||i>=84)return '';const week=chWeekInfo(Math.floor(i/7));if(week.tasks===14)return 'This week is complete. Keep learning at your own pace.';if(i%7===6)return `Week ${week.week+1} closes tonight in ${c.timeZone}. ${14-week.tasks} tasks are still unfinished.`;return `Catch up on earlier days in this week before ${chFriendly(week.close)}. A closed week keeps its recorded score.`}
function chCompact(){const c=chRecord();if(!c||c.withdrawnAt)return '';const t=chTotals(c),i=chIndex(c);return `<section class="card ch-today"><div class="ch-title-row"><span class="eyebrow">84 DAYS OF PROGRESS</span><button class="ch-calendar-icon" data-ch="calendar" aria-label="Open challenge calendar">${journalIcon('calendar')}</button></div><h2>${i<0?'Your next learning habit starts here.':i>=84?'Your challenge record':`Week ${Math.floor(i/7)+1} · keep building`}</h2><p>${esc(chCurrentSummary())}</p><progress value="${t.tasks}" max="168" aria-label="Challenge tasks completed"></progress><p class="hint">${esc(chReminderCopy())}</p><button class="btn" data-ch="overview">${i>=84?'View results':'Continue challenge'} →</button></section>`}
function chHeader(title,back='overview'){return `<header class="learning-heading"><div>${back?`<button class="text-button" data-ch="${back}">← ${back==='progress'?'Progress':back==='overview'?'Challenge':back==='week'?'This week':'Challenge'}</button>`:''}<h1>${esc(title)}</h1></div><button class="ch-calendar-icon" data-ch="calendar" aria-label="Open challenge calendar">${journalIcon('calendar')}</button></header>`}
function chJoinView(){const zone=chZone(),today=chDate(chNow(),zone).date;app.innerHTML=chHeader('84 Days of Progress','progress')+`<section class="card ch-intro"><span class="eyebrow">OPTIONAL · PRIVATE · BADGES</span><h2>One short practice. One reflection.</h2><p>Two tasks per day for 12 weeks. Each week has 14 tasks. You can finish missed days during the same seven-day week.</p><p>Every week starts on your chosen weekday. It closes before the next week begins. Unfinished weeks are marked Incomplete; your completed tasks and badges stay.</p><p>Each task earns one completion point: 14 per week, 168 overall. Practice accuracy is shown separately. No tokens or locked study topics.</p><form id="chJoinForm"><label class="field">Start date<input name="start" type="date" required min="${today}" max="${chAdd(today,30)}" value="${today}"></label><label class="field">Challenge timezone<select name="zone">${[...new Set([zone,'UTC','Asia/Manila','Africa/Cairo'])].map(z=>`<option ${z===zone?'selected':''}>${esc(z)}</option>`).join('')}</select></label><p class="hint">Your challenge dates stay in this timezone when the ship changes clocks.</p><label class="field">Default practice source<select name="bank"><option value="nw" ${state.profile.department==='Deck'?'selected':''}>OIC NW · Deck</option><option value="ew" ${state.profile.department==='Engine'?'selected':''}>OIC EW · Engine</option></select></label><p class="hint">You can also choose OLP or original CBT topics for each practice.</p><button class="btn" type="submit">Join the 12-week challenge</button><p id="chStatus" role="status">${esc(chError)}</p></form></section>`;document.getElementById('chJoinForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);chJoin(f.get('start'),f.get('zone'),f.get('bank'))}}
function chBadgeCards(){return `<section class="card"><h2>Your challenge badges</h2><p class="hint">Earned from your recorded participation.</p><div class="ch-badges">${chBadges().map(b=>`<div class="ch-badge ${b.earned?'earned':''}"><span aria-hidden="true">${b.earned?'✦':'◇'}</span><strong>${esc(b.name)}</strong><small>${esc(b.goal)} · ${b.earned?'Earned':'In progress'}</small></div>`).join('')}</div></section>`}
function chOverview(){const c=chRecord();if(!c){chJoinView();return}const t=chTotals(c),i=chIndex(c),percent=Math.round(t.tasks/168*100),current=Math.max(0,Math.min(11,Math.floor(i/7)));app.innerHTML=chHeader('Your challenge progress','progress')+`<section class="card ch-intro"><span class="eyebrow">84 DAYS OF PROGRESS</span><h2>${t.tasks} / 168 tasks</h2><p>${esc(chCurrentSummary())}</p><progress value="${t.tasks}" max="168" aria-label="Overall challenge completion"></progress><div class="ch-metrics"><div><strong>${percent}%</strong><small>Completion score</small></div><div><strong>${t.days}/84</strong><small>Days completed</small></div><div><strong>${t.weeks}/12</strong><small>Complete weeks</small></div></div><p>Challenge practice: ${t.correct}/${t.answered} source-marked answers matched. Accuracy is separate from task completion.</p><p>${esc(chReminderCopy())}</p><p class="hint">${chFriendly(c.start)} – ${chFriendly(chAdd(c.start,83))} · ${esc(c.timeZone)}. Weeks close before the next start date at midnight.</p>${i>=0&&i<84&&!c.withdrawnAt?`<button class="btn" data-ch-week="${current}">Open this week →</button>`:''}</section><h2>Your 12 weeks</h2><div class="ch-weeks">${Array.from({length:12},(_,w)=>{const row=chWeekInfo(w);return `<button class="card ch-week-card ${w===current&&i>=0&&i<84?'current':''}" data-ch-week="${w}"><strong>Week ${w+1}</strong><small>${esc(chFriendly(row.start))} – ${esc(chFriendly(row.end))}</small><b class="ch-state">${row.status} · ${row.tasks}/14</b><progress value="${row.tasks}" max="14" aria-label="Week ${w+1} tasks"></progress></button>`}).join('')}</div>${chBadgeCards()}${chReminderSettings()}<details class="card"><summary>Challenge participation</summary><p>Leaving keeps your record. The scheduled dates continue, and weeks still close on time.</p><button class="text-button" data-ch="${c.withdrawnAt?'resume':'leave'}">${c.withdrawnAt?'Resume this challenge':'Leave this challenge'}</button><p id="chStatus" role="status">${esc(chError)}</p></details>`;chLearningSummary();chWireReminderSettings()}
function chLearningSummary(){const s=learningStats(),accuracy=s.answered?Math.round(s.correct/s.answered*100):0;app.insertAdjacentHTML('beforeend',`<details class="card"><summary>Your learning record</summary><p>${s.notes} journal entries · ${s.answered} questions practised · ${accuracy}% latest-answer accuracy.</p><p>Challenge completion points measure tasks, not exam accuracy or professional competence.</p></details>`)}
function chWeekView(){const c=chRecord(),w=chWeekInfo(chWeek);app.innerHTML=chHeader('Week '+(chWeek+1))+`<section class="card"><h2>${w.status} · ${w.tasks}/14 tasks</h2><p>${chFriendly(w.start)} – ${chFriendly(w.end)}</p><p>${w.closed?'This week is closed. Its unfinished tasks remain incomplete.':`Finish all tasks before ${chFriendly(w.close)} at 00:00 (${esc(c.timeZone)}). You can catch up on earlier days until then.`}</p><progress value="${w.tasks}" max="14" aria-label="This week’s task completion"></progress></section><div class="ch-days">${Array.from({length:7},(_,j)=>{const day=chWeek*7+j,row=chTask(day),done=chTasksDone(day),open=chOpenDay(day),future=chIndex()<day;return `<button class="card ch-day" data-ch-day="${day}"><span><strong>Day ${day+1} · ${chFriendly(chAdd(c.start,day))}</strong><small>${row.practice?.done?'✓':'○'} Practice · ${row.journal?'✓':'○'} Reflection</small></span><b>${done===2?'Complete':future?'Upcoming':open?'Continue':'Incomplete'}</b></button>`}).join('')}</div><div class="review-pagination"><button class="btn quiet" data-ch-week="${chWeek-1}" ${chWeek===0?'disabled':''}>← Previous week</button><button class="btn quiet" data-ch-week="${chWeek+1}" ${chWeek===11?'disabled':''}>Next week →</button></div>`}
function chPracticeControls(){const bank=chBank(),topics=bank?.topics||reviewSets(bank||{questions:[]}).map(s=>({id:String(s.set),code:'Set '+s.set,title:'Source question grouping'}));return `<label class="field">Practice source<select id="chBankSelect">${chBanks().map(b=>`<option value="${b.id}" ${b.id===chSelection.bank?'selected':''}>${b.title}</option>`).join('')}</select></label>${chLoading?'<p role="status">Loading practice topics…</p>':chLoadError?`<p role="alert">${esc(chLoadError)}</p><button class="btn quiet" data-ch="reloadBank">Retry source</button>`:`<label class="field">Topic / source set<select id="chTopicSelect"><option value="">Mixed eligible questions</option>${topics.map(t=>`<option value="${esc(t.id)}" ${t.id===chSelection.topic?'selected':''}>${esc(t.code||'')} · ${esc(t.title)}</option>`).join('')}</select></label><p class="hint">One short round of up to five eligible single-answer questions. Source sets group questions; they are not official competencies.</p>`}`}
function chDayView(){const c=chRecord(),row=chTask(chDay),open=chOpenDay(chDay),future=chIndex()<chDay,practice=row.practice;app.innerHTML=chHeader('Day '+(chDay+1),'week')+`<p>${chFriendly(chAdd(c.start,chDay))} · Week ${Math.floor(chDay/7)+1}</p><p class="hint">${open?'Complete this day now, or return before this week closes. Catch-up work is recorded on its actual completion date.':future?'This day has not opened yet.':'This day’s week is closed or your participation is inactive.'}</p><section class="card"><h2>${practice?.done?'✓':'○'} Topic practice</h2>${practice?.done?`<p>Task complete · 1 completion point.</p><p>Practice accuracy: ${practice.score}/${practice.ids.length} source-marked answers matched.</p><button class="btn quiet" data-ch-review="${chDay}">Review your answers →</button>`:practice?`<p>${Object.keys(practice.answers).length}/${practice.ids.length} answered.</p><button class="btn" data-ch-practice="${chDay}" ${!open||chLoading?'disabled':''}>Continue practice →</button>`:open?chPracticeControls()+`<button class="btn" data-ch-practice="${chDay}" ${chLoading||chLoadError?'disabled':''}>Start topic practice →</button>`:'<p>Not completed.</p>'}</section><section class="card"><h2>${row.journal?'✓':'○'} Private reflection</h2><p>${row.journal?'Task complete · 1 completion point.':'What did you learn, or what is on your mind? One useful sentence is enough.'}</p>${!row.journal?`<button class="btn" data-ch-reflect="${chDay}" ${!open?'disabled':''}>Write reflection →</button>`:''}</section><p id="chStatus" role="status">${esc(chError||chLoadError)}</p>`;const select=document.getElementById('chBankSelect');if(select)select.onchange=e=>chSelectBank(e.target.value);const topic=document.getElementById('chTopicSelect');if(topic)topic.onchange=e=>{chSelection.topic=e.target.value}}
function chRoundView(){const {round,bank}=chRound();if(!round||!bank){chView='day';chDayView();return}if(round.done){chView='day';chDayView();return}const q=bank.questions.find(q=>q.id===round.ids[round.index]);if(!q){chMessage('This saved question is unavailable. Return to the challenge and report it through Feedback.');chView='day';chDayView();return}const answered=Object.hasOwn(round.answers,q.id),answer=lhCorrect(q)[0],open=chOpenDay(chDay);app.innerHTML=chHeader('Day '+(chDay+1)+' · topic practice','day')+`<p>Question ${round.index+1}/${round.ids.length} · ${esc(bank.title||bank.id)}</p>${!open?'<p role="status">This week is closed. Answers can no longer change.</p>':''}<article class="card review-question"><h2>${esc(q.question)}</h2><div class="review-options">${q.options.map((text,i)=>`<button class="review-option ${answered&&i===answer?'correct':''} ${round.answers[q.id]===i?'selected':''}" data-ch-choice="${i}" ${answered||!open?'disabled':''} aria-pressed="${round.answers[q.id]===i}"><b>${String.fromCharCode(65+i)}</b><span>${esc(text)}</span></button>`).join('')}</div>${answered?`<section class="review-feedback"><strong>${round.answers[q.id]===answer?'Matched the source key':'Revisit this answer'}</strong><p>${esc(q.options[answer])}</p>${q.explanation?`<p>${esc(q.explanation)}</p>`:'<p>Read the marked answer and check the source when uncertain. Source keys are provisional.</p>'}</section>`:''}${bank.original?lhOriginalReferences(q,bank):lhSource(q,bank)}</article><div class="review-pagination"><button class="btn quiet" data-ch="previousQuestion" ${round.index===0?'disabled':''}>← Previous</button>${round.index<round.ids.length-1?`<button class="btn" data-ch="nextQuestion" ${!answered?'disabled':''}>Next →</button>`:`<button class="btn" data-ch="finishPractice" ${!open||!round.ids.every(id=>Object.hasOwn(round.answers,id))?'disabled':''}>Finish practice & record task</button>`}</div><p id="chStatus" role="status">${esc(chError)}</p><p class="hint">Your completion point does not depend on a perfect score. Review feedback before finishing.</p>`}
async function chOpenResults(day){const c=chRecord(),round=chTask(day,c).practice;if(!chReady()||!round?.done)return false;const owner=chOwner(),id=c.id,epoch=++chLoadEpoch;try{await lhLoadBank(round.bank);if(owner!==chOwner()||chRecord()?.id!==id||epoch!==chLoadEpoch)return false;chDay=day;chWeek=Math.floor(day/7);chView='result';page='progress';render();return true}catch(e){if(owner===chOwner()&&epoch===chLoadEpoch)chMessage(e.message);return false}}
function chResultView(){const {round,bank}=chRound();if(!round?.done||!bank){chView='day';chDayView();return}app.innerHTML=chHeader('Day '+(chDay+1)+' · saved practice','day')+`<section class="card"><h2>Saved score: ${round.score}/${round.ids.length}</h2><p>Practice task complete. Reviewing results does not change the task or score.</p></section>${round.ids.map(id=>{const q=bank.questions.find(q=>q.id===id);if(!q)return '<section class="card"><p>This source question is no longer available. Its recorded result is kept.</p></section>';return `<article class="card"><h2>${esc(q.question)}</h2><p>Your answer: ${esc(q.options[round.answers[id]]||'Unavailable')}</p><div class="lh-direct-answer"><strong>Current source-marked answer: ${esc(q.options[lhCorrect(q)[0]]||'Unavailable')}</strong>${q.explanation?`<p>${esc(q.explanation)}</p>`:''}</div>${bank.original?lhOriginalReferences(q,bank):lhSource(q,bank)}</article>`}).join('')}`}
function chProgressCard(){return chRecord()?chCompact()||`<section class="card ch-intro"><h2>12-week challenge</h2><p>Your challenge is inactive. Your scores and badges are kept.</p><button class="btn" data-ch="overview">View challenge →</button></section>`:`<section class="card ch-intro"><span class="eyebrow">OPTIONAL · 12 WEEKS</span><h2>84 Days of Progress</h2><p>Build a learning habit with short topic practice and a private reflection. Catch up within each week and earn badges.</p><button class="btn" data-ch="join">Explore & join →</button></section>`}
function chProgress(){if(chView==='progress'){chBeforeProgress();app.innerHTML=app.innerHTML.replace(/<details class="card"><summary>Top seafarers · planned<\/summary>[\s\S]*?<\/details>/,'');app.insertAdjacentHTML('beforeend',chProgressCard());return}if(chView==='join'&&!chRecord())chJoinView();else if(!chRecord()||chView==='overview')chOverview();else if(chView==='week')chWeekView();else if(chView==='round')chRoundView();else if(chView==='result')chResultView();else chDayView()}
function chMonthShift(month,delta){const [y,m]=month.split('-').map(Number);return new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7)}
function chCalendarMarkup(){const c=chRecord(),first=chCalendarMonth+'-01',padding=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,next=chMonthShift(chCalendarMonth,1),count=chDayNumber(next+'-01')-chDayNumber(first),today=chDate().date,end=chAdd(c.start,83);return `<div class="ch-title-row"><h2 id="chCalendarTitle">Challenge calendar</h2><button class="ch-calendar-icon" data-ch="closeCalendar" aria-label="Close challenge calendar">×</button></div><div class="ch-month-head"><button class="btn quiet" data-ch-month="-1" aria-label="Previous month">‹</button><strong>${new Date(first+'T12:00:00Z').toLocaleDateString('en',{timeZone:'UTC',month:'long',year:'numeric'})}</strong><button class="btn quiet" data-ch-month="1" aria-label="Next month">›</button></div><div class="ch-month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(padding)}${Array.from({length:count},(_,i)=>{const date=chAdd(first,i),day=chDayNumber(date)-chDayNumber(c.start),inside=day>=0&&day<84,done=inside?chTasksDone(day):0,label=!inside?'Outside challenge':done===2?'Complete':done===1?'Partly complete':date<today?'Incomplete':'Not completed';return `<button class="ch-date ${date===today?'today':''} ${done===2?'done':done===1?'partial':''}" ${inside?`data-ch-date="${day}"`:'disabled'} aria-label="${chFriendly(date)}, ${label}${date===c.start?', challenge start':''}${date===end?', challenge finish':''}"><b>${i+1}</b><span aria-hidden="true">${date===c.start?'⚑ ':date===end?'⚐ ':''}${done===2?'✓':done===1?'◐':date===c.start||date===end?'':'·'}</span></button>`}).join('')}</div><p class="hint">⚑ Start · ⚐ Day 84 · ✓ Complete · ◐ Partial · outlined date: today. Select a date to see both tasks.</p><p class="hint">${esc(c.timeZone)} · ${chFriendly(c.start)} – ${chFriendly(end)}</p>`}
function chOpenCalendar(button){if(!chRecord()){chNavigate('join');return}chCalendarOpener=button||document.activeElement;chCalendarMonth=chDate().date.slice(0,7);let dialog=document.getElementById('chCalendar');if(!dialog){dialog=document.createElement('dialog');dialog.id='chCalendar';dialog.className='ch-calendar';dialog.setAttribute('aria-labelledby','chCalendarTitle');document.body.append(dialog);dialog.addEventListener('close',()=>chCalendarOpener?.focus?.());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}const box=button?.getBoundingClientRect?.();if(box)dialog.style.setProperty('--ch-origin',`${Math.max(0,Math.min(100,box.left/window.innerWidth*100))}% 0%`);dialog.innerHTML=chCalendarMarkup();if(!dialog.open)dialog.showModal()}
function chCloseCalendar(){document.getElementById('chCalendar')?.close?.()}
function chDeviceKey(){return 'toolbox-challenge-reminders-v1:'+chOwner()}
function chDevice(){try{return JSON.parse(localStorage.getItem(chDeviceKey()))||{enabled:false,time:'19:00'}}catch{return {enabled:false,time:'19:00'}}}
function chSaveDevice(prefs){try{localStorage.setItem(chDeviceKey(),JSON.stringify(prefs));return true}catch{chMessage('Could not save reminder preferences on this device.');return false}}
function chReminderSettings(){const p=chDevice();return `<section class="card"><h2>Your reminders</h2><p>Today shows your open tasks and a reminder on the last day of each challenge week.</p><label class="field">Daily reminder time (${esc(chRecord().timeZone)})<input id="chReminderTime" type="time" value="${esc(/^\d\d:\d\d$/.test(p.time)?p.time:'19:00')}"></label><button class="btn quiet" data-ch="${p.enabled?'disableAlerts':'enableAlerts'}">${p.enabled?'Turn off browser alerts':'Enable browser alerts'}</button><p class="hint">Browser alerts work only while Toolbox stays open and your browser supports them. Background push notifications are not connected.</p><button class="text-button" data-ch="downloadReminders">Download calendar reminders (.ics) ↓</button><p class="hint">Import the file into your phone calendar for daily reminders and seven-day deadlines when Toolbox is closed. Calendar notification settings control those alerts. Calendar reminders do not track task completion automatically. Change or remove imported events in your calendar.</p><p id="chReminderStatus" role="status" class="hint"></p></section>`}
function chWireReminderSettings(){const input=document.getElementById('chReminderTime');if(input)input.onchange=e=>{if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.target.value))return;const p=chDevice();p.time=e.target.value;chSaveDevice(p)}}
async function chEnableAlerts(){if(!chRecord()||!chReady())return;const owner=chOwner();const status=document.getElementById('chReminderStatus');if(typeof Notification==='undefined'){if(status)status.textContent='This browser cannot enable these alerts. Use the calendar reminder download.';return}try{const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(owner!==chOwner()||!chReady())return;if(permission!=='granted'){if(status)status.textContent='Permission was not granted. In-app reminders still work.';return}const p=chDevice();p.enabled=true;if(chSaveDevice(p)){if(status)status.textContent='Browser reminders enabled on this device while Toolbox stays open.';chSchedule();render()}}catch{if(status)status.textContent='Browser alerts are unavailable here. Use calendar reminders instead.'}}
function chNotify(){const c=chRecord(),p=chDevice(),i=chIndex(c);if(!chReady()||!c||c.withdrawnAt||i<0||i>=84||!p.enabled||typeof Notification==='undefined'||Notification.permission!=='granted'||document.hidden||chDate().time<(p.time||'19:00'))return;const w=chWeekInfo(Math.floor(i/7));if(w.tasks===14||p.last===c.id+':'+i)return;try{const n=new Notification('Toolbox · 84 Days of Progress',{body:i%7===6?`Week ${w.week+1} closes tonight. ${14-w.tasks} tasks unfinished.`:`Week ${w.week+1}: ${w.tasks}/14 tasks. Practise and write your reflection.`,tag:'toolbox-challenge-'+c.id});n.onclick=()=>{window.focus?.();if(chReady())chNavigate('week',i);n.close?.()};p.last=c.id+':'+i;chSaveDevice(p)}catch{p.enabled=false;chSaveDevice(p)}}
function chSchedule(){if(chClock!==null||!chRecord()||!chReady()||document.hidden||chRecord().withdrawnAt||chIndex()>=84)return;chClock=setTimeout(()=>{chClock=null;const old=chRenderedDate,now=chDate().date;if(chReady()&&!document.hidden){chNotify();if(old!==now&&((page==='home')||(page==='progress'&&chView!=='round'))&&!document.activeElement?.matches?.('input,textarea,select'))render();chSchedule()}},60000)}
function chInstant(date,time,zone){const wanted=Date.parse(date+'T'+time+':00Z');let guess=wanted;for(let i=0;i<4;i++){const p=chDate(guess,zone);const actual=Date.parse(p.date+'T'+p.time+':00Z');const diff=wanted-actual;if(!diff)break;guess+=diff}return guess}
function chIcsStamp(time){return new Date(time).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}
function chCalendarFile(c=chRecord(),time=chDevice().time||'19:00'){if(!c)return '';const minutes=Math.min(1439,Number(time.slice(0,2))*60+Number(time.slice(3))+60),deadlineTime=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Toolbox//84 Days of Progress//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];function event(uid,at,title,description){rows.push('BEGIN:VEVENT','UID:'+c.id+'-'+uid+'@toolbox','DTSTAMP:'+chIcsStamp(chNow()),'DTSTART:'+chIcsStamp(at),'DTEND:'+chIcsStamp(at+600000),'SUMMARY:'+title,'DESCRIPTION:'+description,'BEGIN:VALARM','TRIGGER:PT0S','ACTION:DISPLAY','DESCRIPTION:'+title,'END:VALARM','END:VEVENT')}for(let i=0;i<84;i++)event('day'+i,chInstant(chAdd(c.start,i),time,c.timeZone),'Toolbox - Day '+(i+1)+' practice and reflection','Complete a short topic round and one private journal reflection. Catch up within the current challenge week.');for(let w=0;w<12;w++)event('week'+w,chInstant(chAdd(c.start,w*7+6),deadlineTime,c.timeZone),'Toolbox - Week '+(w+1)+' closes tonight','Finish all 14 weekly tasks before midnight in '+c.timeZone+'. Incomplete tasks close with this week.');rows.push('END:VCALENDAR');return rows.map(line=>{const parts=[];let chunk='';for(const char of line){if(new TextEncoder().encode(chunk+char).length>70){parts.push(chunk);chunk=' '+char}else chunk+=char}parts.push(chunk);return parts.join('\r\n')}).join('\r\n')+'\r\n'}
function chDownloadReminders(){if(!chRecord())return;const blob=new Blob([chCalendarFile()],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Toolbox-84-Day-Reminders.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
