document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||!Object.keys(b.dataset).some(k=>k.startsWith('ch')))return;e.stopImmediatePropagation();if(!chReady())return;const d=b.dataset;if(d.ch==='calendar'){chOpenCalendar(b);return}if(d.ch==='closeCalendar'){chCloseCalendar();return}if(d.chMonth){chCalendarMonth=chMonthShift(chCalendarMonth,Number(d.chMonth));const dialog=document.getElementById('chCalendar');if(dialog)dialog.innerHTML=chCalendarMarkup();return}if(d.chDate!==undefined){chCloseCalendar();chNavigate('day',Number(d.chDate));return}if(d.chWeek!==undefined){const w=Number(d.chWeek);if(w>=0&&w<12){chWeek=w;chNavigate('week',w*7)}return}if(d.chDay!==undefined){chSelection={bank:chRecord()?.bank||'nw',topic:''};chNavigate('day',Number(d.chDay));return}if(d.chReflect!==undefined){chStartReflection(Number(d.chReflect));return}if(d.chPractice!==undefined){void chStartPractice(Number(d.chPractice));return}if(d.chReview!==undefined){void chOpenResults(Number(d.chReview));return}if(d.chChoice!==undefined){chChoose(Number(d.chChoice));return}switch(d.ch){case'progress':chNavigate('progress');break;case'join':chNavigate('join');break;case'overview':chNavigate();break;case'week':chNavigate('week',chDay);break;case'day':chNavigate('day',chDay);break;case'previousQuestion':chMoveRound(-1);break;case'nextQuestion':chMoveRound(1);break;case'finishPractice':chFinishPractice();break;case'reloadBank':void chSelectBank(chSelection.bank);break;case'enableAlerts':void chEnableAlerts();break;case'disableAlerts':{const p=chDevice();p.enabled=false;chSaveDevice(p);render();break}case'downloadReminders':chDownloadReminders();break;case'leave':chSetActive(false);break;case'resume':chSetActive(true);break}} ,true);
